const spendByProvider = `-- name: SpendByProvider :many
SELECT coalesce(provider_id, '00000000-0000-0000-0000-000000000000'::uuid) AS provider_id,
       max(provider_kind)::text AS provider_kind,
       count(*)::bigint AS calls,
       sum(input_tokens)::bigint AS input_tokens,
       sum(output_tokens)::bigint AS output_tokens,
       sum(cache_read_tokens)::bigint AS cache_read_tokens,
       sum(cost_usd)::numeric AS cost_usd
FROM llm_calls
WHERE at >= $1 AND at < $2
  AND ($3::uuid IS NULL OR project_id = $3::uuid)
GROUP BY 1
ORDER BY cost_usd DESC
`

type SpendByProviderParams struct {
	At        time.Time
	At_2      time.Time
	ProjectID *uuid.UUID
}

type SpendByProviderRow struct {
	ProviderID      *uuid.UUID
	ProviderKind    string
	Calls           int64
	InputTokens     int64
	OutputTokens    int64
	CacheReadTokens int64
	CostUsd         decimal.Decimal
}

// SpendByProvider, SpendByProject, and SpendByAgent back the dashboard. Genuine
// SQL aggregates, generated like any other query, so the numbers reconcile exactly
// against a direct SUM over llm_calls (BE-1.14).
func (q *Queries) SpendByProvider(ctx context.Context, arg SpendByProviderParams) ([]SpendByProviderRow, error) {
	rows, err := q.db.Query(ctx, spendByProvider, arg.At, arg.At_2, arg.ProjectID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SpendByProviderRow{}
	for rows.Next() {
		var i SpendByProviderRow
		if err := rows.Scan(
			&i.ProviderID,
			&i.ProviderKind,
			&i.Calls,
			&i.InputTokens,
			&i.OutputTokens,
			&i.CacheReadTokens,
			&i.CostUsd,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const spendSince = `-- name: SpendSince :one
SELECT coalesce(sum(cost_usd), 0)::numeric AS total
FROM llm_calls
WHERE at >= $1
  AND ($2::uuid IS NULL OR provider_id = $2::uuid)
  AND ($3::uuid IS NULL OR project_id = $3::uuid)
`

type SpendSinceParams struct {
	At         time.Time
	ProviderID *uuid.UUID
	ProjectID  *uuid.UUID
}

// SpendSince is the ceiling check, evaluated before a call rather than after
// (F-16.10). A mixed setup may have one cheap local provider and one metered one,
// so it is available per provider and in total.
func (q *Queries) SpendSince(ctx context.Context, arg SpendSinceParams) (decimal.Decimal, error) {
	row := q.db.QueryRow(ctx, spendSince, arg.At, arg.ProviderID, arg.ProjectID)
	var total decimal.Decimal
	err := row.Scan(&total)
	return total, err
}

const spendTotal = `-- name: SpendTotal :one
SELECT count(*)::bigint AS calls,
       coalesce(sum(input_tokens), 0)::bigint AS input_tokens,
       coalesce(sum(output_tokens), 0)::bigint AS output_tokens,
       coalesce(sum(cache_read_tokens), 0)::bigint AS cache_read_tokens,
       coalesce(sum(cache_write_tokens), 0)::bigint AS cache_write_tokens,
       coalesce(sum(cost_usd), 0)::numeric AS cost_usd
FROM llm_calls
WHERE at >= $1 AND at < $2
  AND ($3::uuid IS NULL OR project_id = $3::uuid)
`

type SpendTotalParams struct {
	At        time.Time
	At_2      time.Time
	ProjectID *uuid.UUID
}

type SpendTotalRow struct {
	Calls            int64
	InputTokens      int64
	OutputTokens     int64
	CacheReadTokens  int64
	CacheWriteTokens int64
	CostUsd          decimal.Decimal
}

func (q *Queries) SpendTotal(ctx context.Context, arg SpendTotalParams) (SpendTotalRow, error) {
	row := q.db.QueryRow(ctx, spendTotal, arg.At, arg.At_2, arg.ProjectID)
	var i SpendTotalRow
	err := row.Scan(
		&i.Calls,
		&i.InputTokens,
		&i.OutputTokens,
		&i.CacheReadTokens,
		&i.CacheWriteTokens,
		&i.CostUsd,
	)
	return i, err
}

const updateLLMModel = `-- name: UpdateLLMModel :one
UPDATE llm_models
SET display_name = $2, tiers = $3, capabilities = $4,
    price_input = $5, price_output = $6, price_cache_read = $7, price_cache_write = $8,
    max_input_tokens = $9, max_output_tokens = $10, is_enabled = $11, updated_at = now()
WHERE id = $1
RETURNING id, provider_id, model_id, display_name, tiers, capabilities,
          price_input, price_output, price_cache_read, price_cache_write,
          max_input_tokens, max_output_tokens, is_enabled, created_at, updated_at
`

type UpdateLLMModelParams struct {
	ID              uuid.UUID
	DisplayName     string
	Tiers           []string
	Capabilities    json.RawMessage
	PriceInput      decimal.Decimal
	PriceOutput     decimal.Decimal
	PriceCacheRead  *decimal.Decimal
	PriceCacheWrite *decimal.Decimal
	MaxInputTokens  *int32
	MaxOutputTokens *int32
	IsEnabled       bool
}

func (q *Queries) UpdateLLMModel(ctx context.Context, arg UpdateLLMModelParams) (LlmModel, error) {
	row := q.db.QueryRow(ctx, updateLLMModel,
		arg.ID,
		arg.DisplayName,
		arg.Tiers,
		arg.Capabilities,
		arg.PriceInput,
		arg.PriceOutput,
		arg.PriceCacheRead,
		arg.PriceCacheWrite,
		arg.MaxInputTokens,
		arg.MaxOutputTokens,
		arg.IsEnabled,
	)
	var i LlmModel
	err := row.Scan(
		&i.ID,
		&i.ProviderID,
		&i.ModelID,
		&i.DisplayName,
		&i.Tiers,
		&i.Capabilities,
		&i.PriceInput,
		&i.PriceOutput,
		&i.PriceCacheRead,
		&i.PriceCacheWrite,
		&i.MaxInputTokens,
		&i.MaxOutputTokens,
		&i.IsEnabled,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

