const upsertGlobalTierAssignment = `-- name: UpsertGlobalTierAssignment :one
INSERT INTO tier_assignments (scope, scope_id, tier, model_id, fallback_model_id, effort, updated_by)
VALUES ('global', NULL, $1, $2, $3::uuid, $4::text,
        $5::uuid)
ON CONFLICT (tier) WHERE scope = 'global' DO UPDATE
SET model_id = EXCLUDED.model_id,
    fallback_model_id = EXCLUDED.fallback_model_id,
    effort = EXCLUDED.effort,
    updated_by = EXCLUDED.updated_by,
    updated_at = now()
RETURNING id, scope, scope_id, tier, model_id, fallback_model_id, effort, updated_by, created_at, updated_at
`

type UpsertGlobalTierAssignmentParams struct {
	Tier            LlmTier
	ModelID         uuid.UUID
	FallbackModelID *uuid.UUID
	Effort          *string
	UpdatedBy       *uuid.UUID
}

// UpsertTierAssignment writes the global row. Global and project need separate
// statements because their uniqueness is enforced by two partial indexes: a NULL
// scope_id is not equal to itself, so one ON CONFLICT target cannot cover both.
func (q *Queries) UpsertGlobalTierAssignment(ctx context.Context, arg UpsertGlobalTierAssignmentParams) (TierAssignment, error) {
	row := q.db.QueryRow(ctx, upsertGlobalTierAssignment,
		arg.Tier,
		arg.ModelID,
		arg.FallbackModelID,
		arg.Effort,
		arg.UpdatedBy,
	)
	var i TierAssignment
	err := row.Scan(
		&i.ID,
		&i.Scope,
		&i.ScopeID,
		&i.Tier,
		&i.ModelID,
		&i.FallbackModelID,
		&i.Effort,
		&i.UpdatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

